     6	
     7	public class EventDispatcher {
     8	    private final List<ReservationEventListener> listeners = new ArrayList<>();
     9	
    10	    public void subscribe(ReservationEventListener listener) {
    11	        listeners.add(listener);
    12	    }
    13	
    14	    public void unsubscribe(ReservationEventListener listener) {
    15	        listeners.remove(listener);
    16	    }
    17	
    18	    public void dispatch(ReservationEvent event) {
    19	        for (var listener : listeners) {
    20	            listener.onReservationEvent(event);
    21	        }
    22	    }
    23	}
