     6	import com.pousadamarealta.notification.event.ReservationCancelledEvent;
     7	import com.pousadamarealta.notification.event.ReservationEvent;
     8	import java.util.concurrent.atomic.AtomicLong;
     9	
    10	public class FinancialCancellationNotifier implements ReservationEventListener {
    11	    private final MessageStore messageStore;
    12	    private final AtomicLong messageIdCounter;
    13	
    14	    public FinancialCancellationNotifier(MessageStore messageStore, AtomicLong messageIdCounter) {
    15	        this.messageStore = messageStore;
    16	        this.messageIdCounter = messageIdCounter;
    17	    }
    18	
    19	    @Override
    20	    public void onReservationEvent(ReservationEvent event) {
    21	        if (event instanceof ReservationCancelledEvent cancelled) {
    22	            Reservation res = cancelled.reservation();
    23	            ReservationStatus previousStatus = cancelled.previousStatus();
    24	
    25	            if (previousStatus != ReservationStatus.CONFIRMED && previousStatus != ReservationStatus.CHECKED_IN) {
    26	                return;
    27	            }
    28	
    29	            if (res.refund == null || res.refund <= 0) {
    30	                return;
    31	            }
    32	
    33	            String body = String.format(
    34	                "Reembolso necessário:\n\n" +
    35	                "Valor: R$ %.2f\n",
    36	                res.refund
    37	            ).replace(".", ",");
    38	
    39	            Message msg = new Message(
    40	                messageIdCounter.incrementAndGet(),
    41	                "EMAIL",
    42	                "financeiro@pousadamarealta.com.br",
    43	                String.format("Reembolso - reserva %d", res.id),
    44	                body
    45	            );
    46	            messageStore.addMessage(msg);
    47	        }
    48	    }
    49	}
