=== service/ReservationService.java
     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.Reservation;
     4	import com.pousadamarealta.domain.ReservationStatus;
     5	import com.pousadamarealta.domain.RatePlan;
     6	import com.pousadamarealta.domain.Room;
     7	import com.pousadamarealta.notification.EventDispatcher;
     8	import com.pousadamarealta.notification.event.ReservationCancelledEvent;
     9	import com.pousadamarealta.notification.event.ReservationConfirmedEvent;
    10	import java.time.LocalDate;
    11	import java.util.HashMap;
    12	import java.util.List;
    13	import java.util.Map;
    14	import java.util.concurrent.atomic.AtomicLong;
    15	
    16	public class ReservationService {
    17	    private final Map<Long, Reservation> reservations = new HashMap<>();
    18	    private final AtomicLong idCounter = new AtomicLong(0);
    19	    private final RoomService roomService;
    20	    private final PricingService pricingService;
    21	    private final EventDispatcher eventDispatcher;
    22	
    23	    public ReservationService(RoomService roomService, PricingService pricingService, EventDispatcher eventDispatcher) {
    24	        this.roomService = roomService;
    25	        this.pricingService = pricingService;
    26	        this.eventDispatcher = eventDispatcher;
    27	    }
    28	
    29	    public Reservation createReservation(
    30	        int roomNumber,
    31	        String guestName,
    32	        String guestEmail,
    33	        String guestCpf,
    34	        LocalDate checkIn,
    35	        LocalDate checkOut,
    36	        int guests,
    37	        String ratePlan
    38	    ) throws ReservationException {
    39	        Room room = roomService.getRoomByNumber(roomNumber);
    40	        if (room == null) {
    41	            throw new ReservationException("ROOM_NOT_FOUND", "Quarto não encontrado");
    42	        }
    43	
    44	        if (guests > room.capacity()) {
    45	            throw new ReservationException("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade do quarto");
    46	        }
    47	
    48	        if (guests < 1) {
    49	            throw new ReservationException("INVALID_REQUEST", "Pelo menos um hóspede é necessário");
    50	        }
    51	
    52	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    53	            throw new ReservationException("INVALID_REQUEST", "Data de saída deve ser após a data de entrada");
    54	        }
    55	
    56	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
    57	            throw new ReservationException("ROOM_UNAVAILABLE", "Quarto não está disponível para essas datas");
    58	        }
    59	
    60	        long nights = calculateNights(checkIn, checkOut);
    61	        double subtotal = calculateSubtotal(room.nightlyRate(), checkIn, nights);
    62	        double discount = pricingService.calculateDiscount(subtotal, ratePlan);
    63	        double total = pricingService.calculateTotal(subtotal, discount);
    64	
    65	        Reservation reservation = new Reservation(
    66	            idCounter.incrementAndGet(),
    67	            roomNumber,
    68	            guestName,
    69	            guestEmail,
    70	            guestCpf,
    71	            checkIn,
    72	            checkOut,
    73	            guests,
    74	            RatePlan.valueOf(ratePlan),
    75	            (int) nights,
    76	            subtotal,
    77	            discount,
    78	            total,
    79	            ReservationStatus.PENDING,
    80	            0.0,
    81	            null
    82	        );
    83	
    84	        reservations.put(reservation.id, reservation);
    85	        return reservation;
    86	    }
    87	
    88	    public Reservation getReservation(long id) throws ReservationException {
    89	        Reservation res = reservations.get(id);
    90	        if (res == null) {
    91	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reserva não encontrada");
    92	        }
    93	        return res;
    94	    }
    95	
    96	    public Reservation confirmReservation(long id) throws ReservationException {
    97	        Reservation res = getReservation(id);
    98	
    99	        if (res.status != ReservationStatus.PENDING) {
   100	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Apenas reservas pendentes podem ser confirmadas");
   101	        }
   102	
   103	        Reservation updated = res
   104	            .withStatus(ReservationStatus.CONFIRMED)
   105	            .withAmountPaid(res.total);
   106	
   107	        reservations.put(id, updated);
   108	        eventDispatcher.dispatch(new ReservationConfirmedEvent(updated));
   109	        return updated;
   110	    }
   111	
   112	    public Reservation checkIn(long id) throws ReservationException {
   113	        Reservation res = getReservation(id);
   114	
   115	        if (res.status != ReservationStatus.CONFIRMED) {
   116	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Apenas reservas confirmadas podem fazer check-in");
   117	        }
   118	
   119	        Reservation updated = res.withStatus(ReservationStatus.CHECKED_IN);
   120	        reservations.put(id, updated);
   121	        return updated;
   122	    }
   123	
   124	    public Reservation checkOut(long id) throws ReservationException {
   125	        Reservation res = getReservation(id);
   126	
   127	        if (res.status != ReservationStatus.CHECKED_IN) {
   128	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Apenas reservas com check-in podem fazer check-out");
   129	        }
   130	
   131	        Reservation updated = res.withStatus(ReservationStatus.CHECKED_OUT);
   132	        reservations.put(id, updated);
   133	        return updated;
   134	    }
   135	
   136	    public Reservation cancelReservation(long id) throws ReservationException {
   137	        Reservation res = getReservation(id);
   138	
   139	        if (res.status == ReservationStatus.CHECKED_OUT || res.status == ReservationStatus.CANCELLED) {
   140	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Essa reserva não pode ser cancelada");
   141	        }
   142	
   143	        ReservationStatus previousStatus = res.status;
   144	        Double refund = null;
   145	
   146	        if (res.status == ReservationStatus.CONFIRMED || res.status == ReservationStatus.CHECKED_IN) {
   147	            if (res.ratePlan == RatePlan.STANDARD) {
   148	                refund = res.amountPaid;
   149	            } else {
   150	                refund = 0.0;
   151	            }
   152	        }
   153	
   154	        Reservation updated = res
   155	            .withStatus(ReservationStatus.CANCELLED)
   156	            .withRefund(refund);
   157	
   158	        reservations.put(id, updated);
   159	        eventDispatcher.dispatch(new ReservationCancelledEvent(updated, previousStatus));
   160	        return updated;
   161	    }
   162	
   163	    public List<Reservation> getAllReservations() {
   164	        return List.copyOf(reservations.values());
   165	    }
   166	
   167	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   168	        return reservations.values().stream()
   169	            .filter(r -> r.roomNumber == roomNumber && r.status != ReservationStatus.CANCELLED)
   170	            .anyMatch(r -> hasConflict(r, checkIn, checkOut));
   171	    }
   172	
   173	    private boolean hasConflict(Reservation existing, LocalDate checkIn, LocalDate checkOut) {
   174	        return !checkOut.isBefore(existing.checkIn) && !checkIn.isAfter(existing.checkOut.minusDays(1));
   175	    }
   176	
   177	    private long calculateNights(LocalDate checkIn, LocalDate checkOut) {
   178	        return java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
   179	    }
   180	
   181	    private double calculateSubtotal(double baseRate, LocalDate checkIn, long nights) {
   182	        double total = 0;
   183	        LocalDate current = checkIn;
   184	        for (int i = 0; i < nights; i++) {
   185	            double nightlyRate = pricingService.calculateNightlyRate(baseRate, current);
   186	            total += nightlyRate;
   187	            current = current.plusDays(1);
   188	        }
   189	        return pricingService.calculateSubtotal(total, 1);
   190	    }
   191	
   192	    public static class ReservationException extends Exception {
   193	        public final String errorCode;
   194	
   195	        public ReservationException(String errorCode, String message) {
   196	            super(message);
   197	            this.errorCode = errorCode;
   198	        }
   199	    }
   200	}

