   112	    public Reservation checkIn(long id) throws ReservationException {
   113	        Reservation res = getReservation(id);
   114	
   115	        if (res.status != ReservationStatus.CONFIRMED) {
   116	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Apenas reservas confirmadas podem fazer check-in");
   117	        }
   118	
   119	        Reservation updated = res.withStatus(ReservationStatus.CHECKED_IN);
   120	        reservations.put(id, updated);
   121	        return updated;
   122	    }
   123	
   124	    public Reservation checkOut(long id) throws ReservationException {
   125	        Reservation res = getReservation(id);
   126	
   127	        if (res.status != ReservationStatus.CHECKED_IN) {
   128	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Apenas reservas com check-in podem fazer check-out");
   129	        }
   130	
   131	        Reservation updated = res.withStatus(ReservationStatus.CHECKED_OUT);
   132	        reservations.put(id, updated);
