   181	    private double calculateSubtotal(double baseRate, LocalDate checkIn, long nights) {
   182	        double total = 0;
   183	        LocalDate current = checkIn;
   184	        for (int i = 0; i < nights; i++) {
   185	            double nightlyRate = pricingService.calculateNightlyRate(baseRate, current);
   186	            total += nightlyRate;
   187	            current = current.plusDays(1);
   188	        }
   189	        return pricingService.calculateSubtotal(total, 1);
   190	    }
