    10	    public double calculateNightlyRate(double baseRate, LocalDate date) {
    11	        if (isHighSeason(date)) {
    12	            return roundHalfToEven(baseRate * HIGH_SEASON_MULTIPLIER);
    13	        }
    14	        return baseRate;
    15	    }
    16	
    17	    public double calculateSubtotal(double nightlyRate, int nights) {
    18	        return roundHalfToEven(nightlyRate * nights);
    19	    }
    20	
    21	    public double calculateDiscount(double subtotal, String ratePlan) {
    22	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    23	            return roundHalfToEven(subtotal * NON_REFUNDABLE_DISCOUNT_RATE);
    24	        }
    25	        return 0.0;
    26	    }
    27	
    28	    public double calculateTotal(double subtotal, double discount) {
    29	        return roundHalfToEven(subtotal - discount);
    30	    }
    31	
    32	    private boolean isHighSeason(LocalDate date) {
    33	        int month = date.getMonthValue();
    34	        int dayOfMonth = date.getDayOfMonth();
    35	
    36	        if (month == 7) {
    37	            return true;
    38	        }
    39	
    40	        if (month == 12 && dayOfMonth >= 15) {
    41	            return true;
    42	        }
    43	
    44	        if (month >= 1 && month <= 2) {
    45	            return true;
    46	        }
    47	
    48	        return false;
    49	    }
    50	
    51	    private double roundHalfToEven(double value) {
    52	        return Math.round(value * 100.0) / 100.0;
    53	    }
    54	}
