    18	    public String getOccupancyReport(LocalDate date) {
    19	        StringBuilder csv = new StringBuilder();
    20	        csv.append("room,type,reservation,check_in,check_out\n");
    21	
    22	        int occupied = 0;
    23	        List<Reservation> reservations = reservationService.getAllReservations();
    24	
    25	        for (var room : roomService.getAllRooms()) {
    26	            for (var res : reservations) {
    27	                if (res.roomNumber == room.number() &&
    28	                    (res.status == ReservationStatus.CONFIRMED ||
    29	                     res.status == ReservationStatus.CHECKED_IN ||
    30	                     res.status == ReservationStatus.CHECKED_OUT)) {
    31	
    32	                    if (isRoomOccupiedOnDate(res, date)) {
    33	                        csv.append(String.format("%d,%s,%d,%s,%s\n",
    34	                            res.roomNumber,
    35	                            room.type().name,
    36	                            res.id,
    37	                            formatDate(res.checkIn),
    38	                            formatDate(res.checkOut)
    39	                        ));
    40	                        occupied++;
    41	                        break;
    42	                    }
    43	                }
    44	            }
    45	        }
    46	
    47	        csv.append(String.format("total,%d/%d\n", occupied, roomService.getAllRooms().size()));
    48	        return csv.toString();
    49	    }
    50	
    51	    public String getRevenueReport(YearMonth month) {
    52	        StringBuilder csv = new StringBuilder();
    53	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    54	
    55	        double total = 0;
    56	        List<Reservation> reservations = reservationService.getAllReservations();
    57	
    58	        List<Reservation> sorted = reservations.stream()
    59	            .filter(r -> YearMonth.from(r.checkIn).equals(month))
    60	            .filter(r -> r.status == ReservationStatus.CONFIRMED ||
    61	                         r.status == ReservationStatus.CHECKED_IN ||
    62	                         r.status == ReservationStatus.CHECKED_OUT ||
    63	                         r.status == ReservationStatus.CANCELLED)
    64	            .sorted((a, b) -> {
    65	                int dateComp = a.checkIn.compareTo(b.checkIn);
    66	                if (dateComp != 0) return dateComp;
    67	                return Long.compare(a.id, b.id);
    68	            })
    69	            .toList();
    70	
    71	        for (var res : sorted) {
    72	            double amount = res.amountPaid;
    73	            if (res.refund != null && res.refund > 0) {
    74	                amount -= res.refund;
    75	            }
    76	
    77	            if (amount > 0 || res.status == ReservationStatus.CANCELLED) {
    78	                csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n",
    79	                    res.id,
    80	                    res.roomNumber,
    81	                    formatDate(res.checkIn),
    82	                    formatDate(res.checkOut),
    83	                    res.status.name(),
    84	                    amount
    85	                ));
    86	                total += amount;
    87	            }
    88	        }
    89	
    90	        csv.append(String.format("total,,,,,%.2f\n", total));
    91	        return csv.toString();
    92	    }
