    20	) {
    21	    public static DocumentResponse from(Reservation r) {
    22	        return new DocumentResponse(
    23	            "Comprovante de reserva",
    24	            r.id,
    25	            r.guestName,
    26	            formatCpf(r.guestCpf),
    27	            r.roomNumber,
    28	            getRoomType(r.roomNumber),
    29	            formatDateBr(r.checkIn),
    30	            formatDateBr(r.checkOut),
