    38	    private static String formatDateBr(LocalDate date) {
    39	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
    40	    }
    41	
    42	    private static String formatCpf(String cpf) {
    43	        if (cpf.length() == 11) {
    44	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    45	        }
    46	        return cpf;
    47	    }
