    49	    private static String getRoomType(int roomNumber) {
    50	        return switch (roomNumber) {
    51	            case 101, 102 -> "STANDARD";
    52	            case 201, 202 -> "DELUXE";
    53	            case 301 -> "SUITE";
    54	            default -> "UNKNOWN";
    55	        };
    56	    }
    57	}
